#!/usr/bin/env bash
# Build the UniShelf Office augmentation APK.
#
# The script intentionally augments the published UniShelf APK instead of
# rebuilding the Flutter application: the original classes.dex, resources,
# assets and Flutter libraries remain untouched.  It adds:
#   * the upstream MPL-2.0 LibreOfficeKit Java bridge,
#   * a small framework-only OfficeActivity and document surface,
#   * the genuine arm64-v8a LibreOffice runtime from the official F-Droid
#     package, and
#   * blank OOXML/ODF templates generated by that runtime.
#
# Required tools: JDK 17+, Android SDK platform/build-tools, unzip, python3,
# and network access for the first run.  The resulting APK is debug-signed;
# it cannot update the original release because the original signing key is
# not available.
set -Eeuo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WORK="${WORK:-$ROOT/work}"
OUT_DIR="${OUT_DIR:-$ROOT/out}"
ANDROID_HOME="${ANDROID_HOME:-${ANDROID_SDK_ROOT:-}}"
BUILD_TOOLS="${BUILD_TOOLS:-35.0.0}"
API="${API:-35}"
SELFTEST="${SELFTEST:-0}"

BASE_APK="${BASE_APK:-$WORK/UniShelf-arm64-v8a.apk}"
LO_APK="${LO_APK:-$WORK/libreoffice-viewer.apk}"
APKTOOL_JAR="${APKTOOL_JAR:-$WORK/apktool.jar}"
AAPT2_BIN="${AAPT2_BIN:-}"
R8_JAR="${R8_JAR:-$WORK/r8.jar}"

BASE_SHA=f67f918ad2e7f615f8a344dfd84f3aff7e05187ad763963258f3998084613902
LO_SHA=e921bfb14170824572eb1e33643538803681226427948c245084f5e6356c3775

mkdir -p "$WORK" "$OUT_DIR"
export PATH="$WORK/bin:$PATH"

log() { printf '\n== %s ==\n' "$*"; }
fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

if [[ -z "$ANDROID_HOME" || ! -f "$ANDROID_HOME/platforms/android-$API/android.jar" ]]; then
  fail "Set ANDROID_HOME to an SDK containing platforms/android-$API"
fi
if [[ ! -x "$ANDROID_HOME/build-tools/$BUILD_TOOLS/aapt2" ]]; then
  fail "Android build-tools $BUILD_TOOLS not installed"
fi

download() {
  local url="$1" dest="$2"
  if [[ ! -s "$dest" ]]; then
    log "Downloading $url"
    mkdir -p "$(dirname "$dest")"
    curl -fL --retry 4 --retry-delay 3 -o "$dest.part" "$url"
    mv "$dest.part" "$dest"
  fi
}

download "https://github.com/ZamCan/UniShelf-App/releases/download/v1.0.0/UniShelf-arm64-v8a.apk" "$BASE_APK"
download "https://f-droid.org/repo/org.documentfoundation.libreoffice_135.apk" "$LO_APK"
download "https://github.com/iBotPeaches/Apktool/releases/download/v2.11.1/apktool_2.11.1.jar" "$APKTOOL_JAR"

check_sha() {
  local file="$1" expected="$2"
  local actual
  actual="$(sha256sum "$file" | awk '{print $1}')"
  [[ "$actual" == "$expected" ]] || fail "checksum mismatch for $file: $actual != $expected"
}
check_sha "$BASE_APK" "$BASE_SHA"
check_sha "$LO_APK" "$LO_SHA"

# Apktool's bundled aapt2 is x86_64 even when it runs on an arm64 Termux/proot
# host.  Reuse the aapt2 from Termux in that case.  Normal CI hosts do not need
# this branch.
if [[ "$(uname -m)" == "aarch64" && -n "$AAPT2_BIN" ]]; then
  log "Patching Apktool's x86_64 aapt2 with $AAPT2_BIN"
  python3 - "$APKTOOL_JAR" "$AAPT2_BIN" "$WORK/apktool-aarch64.jar" <<'PY'
import sys, zipfile
src, aapt, dst = sys.argv[1:]
with zipfile.ZipFile(src) as zin, zipfile.ZipFile(dst, "w", zipfile.ZIP_DEFLATED) as zout:
    for info in zin.infolist():
        data = zin.read(info.filename)
        if info.filename == "prebuilt/linux/aapt2_64":
            data = open(aapt, "rb").read()
        zout.writestr(info, data)
PY
  APKTOOL_JAR="$WORK/apktool-aarch64.jar"
fi

log "Decoding base APK (resources only; classes.dex stays untouched)"
rm -rf "$WORK/base-decoded"
java -jar "$APKTOOL_JAR" d -s -f "$BASE_APK" -o "$WORK/base-decoded" >/dev/null

log "Extracting the upstream arm64 LibreOffice engine"
rm -rf "$WORK/engine"
mkdir -p "$WORK/engine"
unzip -q "$LO_APK" \
  'lib/arm64-v8a/*' \
  'assets/program/*' \
  'assets/share/*' \
  'assets/unpack/*' \
  -d "$WORK/engine"

DEST_LIB="$WORK/base-decoded/lib/arm64-v8a"
mkdir -p "$DEST_LIB"
for lib in \
  libc++_shared.so libfreebl3.so liblo-native-code.so libnspr4.so \
  libnss3.so libnssckbi.so libnssdbm3.so libnssutil3.so libplc4.so \
  libplds4.so libsmime3.so libsoftokn3.so libsqlite3.so libssl3.so; do
  [[ -s "$WORK/engine/lib/arm64-v8a/$lib" ]] || fail "missing engine library $lib"
  cp "$WORK/engine/lib/arm64-v8a/$lib" "$DEST_LIB/$lib"
done

# The upstream NSS module needs SQLite's SQLITE_3 versioned ABI.  The base
# Flutter APK carries an unversioned SQLite build, so the engine copy replaces
# it; this is the same library used by the official LibreOffice Android
# package.  The original classes.dex is not changed.
cp "$WORK/engine/lib/arm64-v8a/libsqlite3.so" "$DEST_LIB/libsqlite3.so"

for dir in program share unpack; do
  rm -rf "$WORK/base-decoded/assets/$dir"
  cp -a "$WORK/engine/assets/$dir" "$WORK/base-decoded/assets/$dir"
done
mkdir -p "$WORK/base-decoded/assets/unishelf_office"
cp -a "$ROOT/office/assets/unishelf_office/." "$WORK/base-decoded/assets/unishelf_office/"
if [[ "$SELFTEST" == "1" ]]; then
  cp "$ROOT/office/assets/unishelf_office/selftest.docx" \
     "$WORK/base-decoded/assets/unishelf_office/selftest.docx"
else
  rm -f "$WORK/base-decoded/assets/unishelf_office/selftest.docx"
fi

log "Compiling Java bridge and Office activity"
rm -rf "$WORK/classes" "$WORK/dex"
mkdir -p "$WORK/classes" "$WORK/dex"
mapfile -t SOURCES < <(find "$ROOT/office/src" -name '*.java' | sort)
javac -source 8 -target 8 -Xlint:-options \
  -cp "$ANDROID_HOME/platforms/android-$API/android.jar" \
  -d "$WORK/classes" "${SOURCES[@]}"

# Build-tools 34's D8 (R8 8.2.2) has a reproducible NPE on javac anonymous
# inner classes.  Prefer R8 8.7.18 from the official release, and fall back to
# a platform d8 only if the caller explicitly provides one.
if [[ ! -s "$R8_JAR" ]]; then
  download "https://storage.googleapis.com/r8-releases/raw/8.7.18/r8.jar" "$R8_JAR"
fi
java -cp "$R8_JAR" com.android.tools.r8.D8 --min-api 24 \
  --lib "$ANDROID_HOME/platforms/android-$API/android.jar" \
  --output "$WORK/dex" $(find "$WORK/classes" -name '*.class' | sort)
cp "$WORK/dex/classes.dex" "$WORK/base-decoded/classes2.dex"

log "Registering OfficeActivity and runtime flags"
python3 "$ROOT/tools/patch-manifest.py" "$WORK/base-decoded/AndroidManifest.xml" \
  $( [[ "$SELFTEST" == "1" ]] && printf '%s' --debug )

# Compress .so entries: extractNativeLibs=true means Android will install the
# extracted libraries, and keeping the 187 MB engine compressed substantially
# reduces the APK and download size.
python3 - "$WORK/base-decoded/apktool.yml" <<'PY'
import sys
from pathlib import Path
p = Path(sys.argv[1])
s = p.read_text()
s = s.replace("doNotCompress:\n- arsc\n- png\n- so\n", "doNotCompress:\n- arsc\n- png\n")
p.write_text(s)
PY

log "Building APK"
BUILD_FLAGS=()
if [[ "$SELFTEST" == "1" ]]; then
  BUILD_FLAGS+=(--debug)
fi
java -Xmx2g -jar "$APKTOOL_JAR" b "${BUILD_FLAGS[@]}" "$WORK/base-decoded" \
  -o "$OUT_DIR/UniShelf-Office-unsigned.apk" >"$WORK/apktool-build.log" 2>&1 || {
    tail -80 "$WORK/apktool-build.log" >&2
    exit 1
  }

KEYSTORE="${KEYSTORE:-$WORK/debug.keystore}"
if [[ ! -f "$KEYSTORE" ]]; then
  log "Creating an Android debug keystore"
  keytool -genkeypair -keystore "$KEYSTORE" -storepass android \
    -alias androiddebugkey -keypass android -keyalg RSA -keysize 2048 \
    -validity 10000 -dname 'CN=Android Debug,O=Android,C=US' >/dev/null
fi

SIGNED="$OUT_DIR/UniShelf-Office-arm64-debug.apk"
if [[ "$SELFTEST" == "1" ]]; then
  SIGNED="$OUT_DIR/UniShelf-Office-selftest-debug.apk"
fi
log "Signing $SIGNED"
"$ANDROID_HOME/build-tools/$BUILD_TOOLS/apksigner" sign \
  --ks "$KEYSTORE" --ks-pass pass:android --key-pass pass:android \
  --v1-signing-enabled true --v2-signing-enabled true \
  --out "$SIGNED" "$OUT_DIR/UniShelf-Office-unsigned.apk"

"$ANDROID_HOME/build-tools/$BUILD_TOOLS/apksigner" verify --print-certs "$SIGNED" >/dev/null
unzip -t "$SIGNED" >/dev/null
printf '\nBuilt: %s\n' "$SIGNED"
printf 'Size:  %s bytes\n' "$(stat -c%s "$SIGNED")"
printf 'SHA-256: %s\n' "$(sha256sum "$SIGNED" | awk '{print $1}')"
